import XCTest
@testable import ColorComposerCore

/// Replays the golden-vector solver parity corpus generated by the Elixir
/// `color_matching` service (viamin/color_matching#111, `mix parity.generate`)
/// through `WeightedSquaredErrorScorer` and `CompositionSolver`.
///
/// The corpus is committed verbatim at `Fixtures/parity/v1/corpus.json` and is
/// stamped with an `algorithm_version`; when that number changes upstream,
/// every expectation has moved and this fixture must be refreshed in step.
final class SolverParityCorpusTests: XCTestCase {
    private static let scoreAccuracy = 1e-12

    // MARK: - Corpus decoding

    private struct ParityCorpus: Decodable {
        let algorithmVersion: Int
        let scorer: String
        let selection: String
        let missingPolicy: String
        let lightSources: [String]
        let scenarios: [Scenario]
    }

    private struct Scenario: Decodable {
        let id: String
        let description: String
        let palette: [Candidate]
        let target: Vector
        let weights: [String: Double]
        let expected: Expected

        struct Candidate: Decodable {
            let index: Int
            let hexColor: String
            let channels: [String: Double]
        }

        struct Vector: Decodable {
            let channels: [String: Double]
        }

        struct Expected: Decodable {
            let selectedIndex: Int?
            let selectedHexColor: String?
            let error: Double?
            let tieBroke: Bool?
            let tiedIndices: [Int]
            let scores: [RecordedScore]
        }

        struct RecordedScore: Decodable, Equatable {
            let index: Int
            let score: Entry

            /// The corpus encodes excluded candidates as the string "excluded"
            /// instead of a number.
            enum Entry: Equatable, Decodable {
                case score(Double)
                case excluded

                init(from decoder: Decoder) throws {
                    let container = try decoder.singleValueContainer()
                    if let value = try? container.decode(Double.self) {
                        self = .score(value)
                        return
                    }
                    let marker = try container.decode(String.self)
                    guard marker == "excluded" else {
                        throw DecodingError.dataCorruptedError(
                            in: container,
                            debugDescription: "Unknown score entry: \(marker)"
                        )
                    }
                    self = .excluded
                }
            }
        }
    }

    // MARK: - Loading

    private func loadCorpus() throws -> ParityCorpus {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/parity/v1/corpus.json")
        let data = try Data(contentsOf: url)
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(ParityCorpus.self, from: data)
    }

    // MARK: - Corpus → domain mapping

    /// Weight keys outside the five canonical conditions (for example the
    /// corpus's `ultraviolet`) are dropped, mirroring `PaletteColorDTO.toDomain`.
    private func channelWeights(_ raw: [String: Double]) -> ChannelWeights {
        ChannelWeights(
            white: raw["white"] ?? 0,
            red: raw["red"] ?? 0,
            green: raw["green"] ?? 0,
            blue: raw["blue"] ?? 0,
            lps: raw["lps"] ?? 0
        )
    }

    private func paletteColor(
        _ candidate: Scenario.Candidate,
        _ scenarioID: String
    ) throws -> PaletteColor {
        let rgb = try XCTUnwrap(
            RGBColor(hex: candidate.hexColor),
            "\(scenarioID): corpus hex \(candidate.hexColor) must parse"
        )
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (key, value) in candidate.channels {
            guard let condition = LightingCondition(rawValue: key) else { continue }
            responses[condition] = IlluminationResponse(brightness: value)
        }
        return PaletteColor(
            id: candidate.index,
            hex: candidate.hexColor,
            rgb: rgb,
            responses: responses
        )
    }

    private func targetVector(_ vector: Scenario.Vector) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) {
                brightness[condition] = value
            }
        }
        return TargetResponseVector(brightness)
    }

    private func replayPalette(_ scenario: Scenario) throws -> [PaletteColor] {
        try scenario.palette.map { try paletteColor($0, scenario.id) }
    }

    // MARK: - Metadata

    func testCorpusMetadataMatchesSupportedAlgorithmVersion() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(
            corpus.algorithmVersion, 1,
            "A bumped algorithm_version means every expectation moved; refresh the fixture and this pin in step."
        )
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, ["white", "red", "green", "blue", "lps"])
        XCTAssertGreaterThanOrEqual(corpus.scenarios.count, 12)
        XCTAssertTrue(corpus.scenarios.contains { $0.expected.tieBroke == true }, "Corpus must include tie cases.")
        XCTAssertTrue(
            corpus.scenarios.contains { scenario in
                scenario.expected.scores.contains { $0.score == .excluded }
            },
            "Corpus must include missing-measurement exclusions."
        )
        XCTAssertTrue(
            corpus.scenarios.contains { $0.expected.selectedIndex == nil },
            "Corpus must include an all-excluded scenario."
        )
    }

    // MARK: - Scorer replay

    /// Upstream consumption recipe (color_matching README): score every palette
    /// color against the target using the scenario's weights and assert exact
    /// agreement with the recorded score table, selection, error, and tie
    /// indices.
    func testScorerReplayMatchesCorpusExactly() throws {
        let corpus = try loadCorpus()
        let scorer = WeightedSquaredErrorScorer()

        for scenario in corpus.scenarios {
            let palette = try replayPalette(scenario)
            let target = targetVector(scenario.target)
            let weights = channelWeights(scenario.weights)

            var ranked: [(index: Int, score: Double)] = []
            for (position, color) in palette.enumerated() {
                let recorded = scenario.expected.scores[position]
                XCTAssertEqual(
                    recorded.index, position,
                    "\(scenario.id): score table rows must follow palette order"
                )

                let result = scorer.score(candidate: color, target: target, weights: weights)
                switch (result, recorded.score) {
                case (.score(let actual), .score(let expected)):
                    XCTAssertEqual(
                        actual, expected, accuracy: Self.scoreAccuracy,
                        "\(scenario.id): candidate \(position)"
                    )
                    ranked.append((position, actual))
                case (.excluded, .excluded):
                    break
                default:
                    XCTFail(
                        "\(scenario.id): candidate \(position) produced \(result) " +
                        "but corpus recorded \(recorded.score)"
                    )
                }
            }

            assertSelection(
                ranked: ranked,
                palette: palette,
                expected: scenario.expected,
                scenarioID: scenario.id
            )
        }
    }

    /// Earliest-wins selection over the ranked candidates, mirroring
    /// `CompositionSolver.bestCandidate` and the corpus `selection` policy.
    private func earliestWinner(
        _ ranked: [(index: Int, score: Double)]
    ) -> (index: Int, score: Double)? {
        var winner: (index: Int, score: Double)?
        for entry in ranked where entry.score < (winner?.score ?? .infinity) {
            winner = entry
        }
        return winner
    }

    private func assertSelection(
        ranked: [(index: Int, score: Double)],
        palette: [PaletteColor],
        expected: Scenario.Expected,
        scenarioID: String
    ) {
        let winner = earliestWinner(ranked)

        XCTAssertEqual(winner?.index as Int?, expected.selectedIndex, "\(scenarioID): selected index")
        if let winner {
            guard let expectedError = expected.error else {
                return XCTFail("\(scenarioID): winner recorded but corpus has no expected error")
            }
            XCTAssertEqual(winner.score, expectedError, accuracy: Self.scoreAccuracy, "\(scenarioID): winner error")
            XCTAssertEqual(palette[winner.index].hex, expected.selectedHexColor, "\(scenarioID): selected hex")
        } else {
            XCTAssertNil(expected.error, "\(scenarioID): no winner means no recorded error")
        }

        let tied: [Int]
        if let winner {
            tied = ranked
                .filter { abs($0.score - winner.score) <= Self.scoreAccuracy }
                .map(\.index)
        } else {
            tied = []
        }
        XCTAssertEqual(tied, expected.tiedIndices, "\(scenarioID): tied indices")
        // With no selection the corpus records `tie_broke: null`, not false.
        XCTAssertEqual(expected.tieBroke, winner == nil ? nil : tied.count > 1, "\(scenarioID): tie_broke")
        if let selected = expected.selectedIndex {
            XCTAssertEqual(tied.first, selected, "\(scenarioID): selection must be the earliest tied index")
        }
    }

    // MARK: - Solver replay

    /// Drives the production `CompositionSolver` (default scorer, whose
    /// `bestCandidate` performs the earliest-wins tie-break) on a 1×1 grid per
    /// scenario and asserts the recorded selection and error.
    func testSolverSelectionAgreesWithCorpus() throws {
        let corpus = try loadCorpus()
        var replayed = 0

        for scenario in corpus.scenarios {
            let weights = channelWeights(scenario.weights)
            let target = targetVector(scenario.target)

            // Grids always carry a value, so a target that omits an active
            // channel (target-side exclusion) can only be replayed at the
            // scorer level above.
            let active = weights.activeConditions
            guard active.allSatisfy({ target.value(for: $0) != nil }) else { continue }

            var grids: [LightingCondition: BrightnessGrid] = [:]
            for condition in active {
                let value = try XCTUnwrap(target.value(for: condition), "\(scenario.id)")
                grids[condition] = BrightnessGrid(width: 1, height: 1, fill: value)
            }
            let palette = try replayPalette(scenario)

            let result = try CompositionSolver().solve(
                palette: palette,
                sourceGrids: grids,
                weights: weights
            )
            replayed += 1

            XCTAssertEqual(
                result.colorIndex(x: 0, y: 0) as Int?,
                scenario.expected.selectedIndex,
                "\(scenario.id): solver selection"
            )
            if let selectedIndex = scenario.expected.selectedIndex {
                let expectedError = try XCTUnwrap(scenario.expected.error, "\(scenario.id)")
                XCTAssertEqual(
                    result.error(x: 0, y: 0), expectedError,
                    accuracy: Self.scoreAccuracy, "\(scenario.id): solver error"
                )
                let selectedHex = try XCTUnwrap(scenario.expected.selectedHexColor, "\(scenario.id)")
                XCTAssertEqual(result.palette[selectedIndex].hex, selectedHex, "\(scenario.id): solver selected hex")
            } else {
                XCTAssertEqual(result.error(x: 0, y: 0), .infinity, "\(scenario.id): unmatched cell records infinite error")
                XCTAssertEqual(result.unmatchedCellCount, 1, "\(scenario.id): the single cell must be unmatched")
            }
        }

        XCTAssertGreaterThanOrEqual(
            replayed, 11,
            "Only target-side-exclusion scenarios may be skipped by the solver replay"
        )
    }
}
